// Every generated file with its exact content. `generate` writes them; `generate --check` and the
// generator test compare them with the committed files.
import {
  clientMessageExamples,
  errorExamples,
  eventExamples,
  operationExamples,
  serverMessageExamples,
} from '../examples/index.js';
import { buildJsonSchemaBundle } from './json-schema.js';
import { buildOpenApiDocument } from './openapi.js';

/** Paths relative to the package root; the Rust code generation and the checks rely on these names. */
export const GENERATED_PATHS = {
  openApi: 'generated/openapi.json',
  jsonSchema: 'generated/json-schema/pulse-contract.schema.json',
  examples: 'generated/examples.json',
} as const;

const json = (value: unknown) => `${JSON.stringify(value, null, 2)}\n`;

export function generatedFiles(): [string, string][] {
  return [
    [GENERATED_PATHS.openApi, json(buildOpenApiDocument())],
    [GENERATED_PATHS.jsonSchema, json(buildJsonSchemaBundle())],
    [
      GENERATED_PATHS.examples,
      json({
        $comment:
          '@generated by `pnpm --filter @pulse/contract generate` from packages/contract/src/examples; do not edit.',
        operations: operationExamples,
        events: eventExamples,
        clientMessages: clientMessageExamples,
        serverMessages: serverMessageExamples,
        errors: errorExamples,
      }),
    ],
  ];
}
